node.script:
function OnStart(so_self, length)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local pos = StageObject_GetPosition(so_self);
	KeyValueStore_SetKeyValueFloat3(kvs, "base_pos", pos[0], pos[1], pos[2]);
	Actor_SetActorFlag(so_self, "STATIC", false);
}

function OnUpdate(so_actor, time_key, length)
{
	local kvs = StageObject_GetKeyValueStore(so_actor);
	local base_pos = KeyValueStore_GetKeyValue(kvs, "base_pos");
	StageObject_SetPosition(so_actor, base_pos[0], base_pos[1], base_pos[2]);

	local offset = cos(2 * PI * time_key / length);
	offset *= offset;
	local new_pos = StageObject_GetPositionWithOffset(so_actor, 0, 10 * offset, 0);
	StageObject_SetPosition(so_actor, new_pos[0], new_pos[1], new_pos[2]);
}

node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{

	local so_glow_effect = Stage_GetStageObjectById("cave_glow_effect");
	local quest_id = "quests/dlc_1_main.nut";

	// set campfire fast travel available if dlc1 quest is complete
	Game_SetFeatureAvailable("CAMPFIRE_FAST_TRAVEL", true);


	if (so_glow_effect != null)
	{

		if (Game_IsQuestCompleted(quest_id) || Game_IsQuestCurrent(quest_id)) {

			 StageObject_SetVisible(so_glow_effect, true);
			 return;

		}

		if (StageObject_IsVisible(so_glow_effect))
			StageObject_SetVisible(so_glow_effect, false);

	}



}

node.interaction_1_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	local quest_id = "quests/dlc_1_main.nut";


	if (Game_IsQuestCompleted(quest_id))
		return true;

	if(Game_IsQuestCurrent(quest_id)){

		if (Game_IsQuestGoalCompleted(quest_id, "PHASE_GO_TO_ENTRANCE", "GOAL_INVESTIGATE"))
		{
			return true;
		}

	}

	return false;



}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetCinemaMode(true);

	local script_start = @"
		Game_SetCinemaMode(true);
		Actor_SetActorFlag($so_activator, ""SOLID"", false);
		";

	local entrance = so_self;
	Game_SetStagePointOfInterestCompleted(entrance);

	local entrance_pos = StageObject_GetPosition(entrance);

	script_start = string_replace(script_start, "$so_activator", so_activator.tostring());


	if (Game_IsRecipeCrafted("ROPE_AND_HOOK"))
	{

		Actor_QueueActionRunScript(so_activator, script_start);

		Actor_QueueActionWaitForCommandWord(so_self, "wait");
		Actor_QueueActionMoveToDistanceFromActor(so_activator, so_self, 35);

		Actor_QueueActionTurnTowardsPosition(so_activator,entrance_pos[0], entrance_pos[1]);

		Actor_QueueActionSendCommandWord(so_activator, so_self, "wait");
		Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", true);
		Actor_QueueActionPlayAnimation(so_activator, "enter_tomb_outside", false);

		//Game_SetCinemaMode(true);
		Game_SetScreenFadeOutWithCommand(3, "travel_to_stage", so_self, 3.0);
	}
	else
	{

		Game_SetCinemaMode(false);
		Game_AddActorNotification(so_activator, LOC_TEXT("That looks deep. I need to invent and craft a [GREEN]Rope and Hook[WHITE] to climb down there! [EMOJI=thinking face]."));

		Game_SetRecipeUnlocked("ROPE_AND_HOOK", true, true);
		Actor_SetInteractionEnabled(so_self, "descend", true);

	}

	//local script_end = @"
		//Game_SetCinemaMode(false);
		//Actor_SetActorFlag($so_activator, ""SOLID"", true);
	//    ";

	//script_end = string_replace(script_end, "$so_activator", so_activator.tostring());
	//Actor_QueueActionRunScript(so_activator, script_end);
	//Game_SetScreenFadeOutWithCommand(0.6, "travel_to_stage", so_self, 0.65);

}

node.interaction_2_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	local quest_id = "quests/dlc_1_main.nut";

	// Hide this interaction for now. Add it back in when DLC is officially launched.
	if (!IAP_IsItemPurchased("DLC1"))
		return false;

	if (Game_IsQuestCurrent(quest_id))
	{
		if (Game_GetQuestPhaseId(quest_id) == "PHASE_GO_TO_ENTRANCE")
			return true;

		if (Game_IsQuestGoalCompleted(quest_id, "PHASE_GO_TO_LINK_TOWER", "GOAL_SCAN_ANOMALIES"))
		{
			return false;
		}
	}
	else if (Game_IsQuestCompleted(quest_id))
	{
		return false;
	}

	return true;

}

node.interaction_2_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
   if (!Actor_IsAnimationPlaying(so_activator, "idle-2"))
	   Actor_QueueActionPlayAnimation(so_activator, "idle-2", false);

   local quest_id = "quests/dlc_1_main.nut";

   if (Game_IsQuestCompleted(quest_id))
		return true;

   if (Game_IsQuestCurrent(quest_id))
   {
	   if (Game_GetQuestPhaseId(quest_id) == "PHASE_GO_TO_LINK_TOWER")
	   {
		   Game_QuestGoalCompleted(quest_id, "PHASE_GO_TO_LINK_TOWER", "GOAL_SCAN_ANOMALIES");
		   local text_0 = LOC_TEXT("Strange...");
		   Game_AddActorNotification(so_activator, text_0);
		   return;
	   }
   }

   if(Game_IsQuestGoalCompleted(quest_id, "PHASE_GO_TO_LINK_TOWER", "GOAL_SCAN_ANOMALIES"))
   {
	   local text_0 = LOC_TEXT("The signal comes from underground? [EMOJI=thinking face].");
	   Game_AddActorNotification(so_activator, text_0);
   }
   else
   {
	   Game_AddActorNotification(so_activator, "[EMOJI=face with raised eyebrow]");
   }
}
